<?php

declare(strict_types=1);

namespace Pig\CodingAgent\Test;

/**
 * Pictures that are pictures. An image on its way into the conversation is decoded and fitted
 * inside the provider's limits (`Utils\ImageProcess`), so eight bytes of PNG signature and nothing
 * else is no longer an image — it is one that cannot be read, and is left out. These are 4×3,
 * written by GD and kept as bytes, so no test needs GD to make them.
 */
final class TinyImages
{
    public const string PNG_BASE64 = 'iVBORw0KGgoAAAANSUhEUgAAAAQAAAADCAIAAAA7ljmRAAAACXBIWXMAAA7EAAAOxAGVKw4bAAAADElEQVQImWNgIAoAAAAnAAGfWjwcAAAAAElFTkSuQmCC';

    public const string JPEG_BASE64 = '';

    public static function png(): string
    {
        return (string) base64_decode(self::PNG_BASE64, true);
    }

    public static function jpeg(): string
    {
        return (string) base64_decode(self::JPEG_BASE64, true);
    }
}
